            "bz_use_review": "优先复核使用环境",
            "bz_action_activity": "先疏通走道与门窗，改善照明和通风。如果这里实际适合办公或日常活动，再安排桌椅与使用动线。",
            "bz_action_rest": "优先检查休息座位、床头支撑、噪音和夜间眩光。若是客厅，安排舒适座位与不互相打扰的交流区。",
            "bz_action_study": "让桌面整洁、座椅稳定、光线不刺眼，把书桌避开持续噪音源；再按实际读书或工作习惯微调。",
            "bz_action_review": "先检查这个方位是否长期睡卧或久坐，以及通风、采光、噪音和杂物。先解决实际不舒适的问题，再考虑小范围调整。",
            "bz_avoid_activity": "不必只凭吉位改大门、买鱼缸或搬动大件；不要为摆件堵住通道。",
            "bz_avoid_rest": "不要用星名代替睡眠或健康判断，也不必只凭方位搬床；先按真实舒适度处理。",
            "bz_avoid_study": "避免背光、屏幕反光和通道穿过座位；不需要额外购买所谓文昌摆件。",
            "bz_avoid_review": "传统凶星名称不是现实事故结论。无需停用房间、改建卫生间或封堵出入口，必要维修仍应照常进行。",

            "xk_guide_center": "住宅中心",
            "xk_pattern_balanced_title": "前方活动，后方休息",
            "xk_pattern_balanced_body": "这张盘的活动重点在朝向一侧，休息重点在坐后一侧。先看下图的具体方位；标为“保持安静”的区域优先按安静原则处理。",
            "xk_pattern_front_title": "前方做好动静分区",
            "xk_pattern_front_body": "活动与休息的重点都落在朝向一侧。同一方位有两种需求，要把通行、活动和安静休息的位置分开，不能整片一概催旺。",
            "xk_pattern_back_title": "后方做好动静分区",
            "xk_pattern_back_body": "活动与休息的重点都落在坐后一侧。先检查这里实际是什么房间，再把动线与安静区域分开；不是后方所有位置都要摆放重物。",
            "xk_pattern_reversed_title": "前方休息，后方活动",
            "xk_pattern_reversed_body": "这张盘的活动重点在坐后，休息重点在朝向一侧。先核对现有用途、采光和噪音，再考虑小范围调整，不用只凭格局名称大改房屋。",
            "xk_pattern_distributed_title": "按方位分别安排",
            "xk_pattern_distributed_body": "这张盘不属于前后集中的四类格局。先查看需要保持安静的区域，再按下图分别安排活动和休息用途。",
            "xk_use_quiet": "保持安静",
            "xk_use_separate": "动静分区",
            "xk_use_activity": "通畅明亮",
            "xk_use_rest": "安静稳靠",
            "xk_use_everyday": "日常维护",
            "xk_reason_quiet": "山向组合含2或5，传统规则以静为先；即使同时有当运星，本页也优先提示安静处理。",
            "xk_reason_separate": "当运山星与向星同在这里，因此同时有活动和安静休息两种需求。",
            "xk_reason_activity": "当运向星落在这里，传统上把它作为活动、出入和纳气的重点。",
            "xk_reason_rest": "当运山星落在这里，传统上把它作为安静休息与稳定支撑的重点。",
            "xk_reason_everyday": "这里没有触发本页的当运山向星或2/5优先规则，按实际房间用途维护即可。",
            "xk_action_quiet": "先移走持续发声或震动的设备，整理杂物。若这里是门口，保持通行正常，把门扇异响和碰撞声处理好。",
            "xk_action_separate": "靠门窗一侧留出通道和光线；较内侧安排安静座位或休息区，用家具做轻分区，先避免活动互相干扰。",
            "xk_action_activity": "先疏通门窗与走道，修好照明、保持通风；若实际条件适合，可优先安排日常活动或工作位置。",
            "xk_action_rest": "先减少噪音与夜间眩光，让床头、椅背有稳固支撑；保留正常通风，再按实际房间功能调整位置。",
            "xk_action_everyday": "清理杂物，保证照明、通风和通行；按厨房、卧室或工作区的实际需要使用，不必额外改造。",
            "xk_avoid_quiet": "不为“催旺”额外放置水泵、音箱等持续扰动设备，也不用封门或停用房间。必要维修照常安排。",
            "xk_avoid_separate": "别把电视、音箱、水泵与床头或安静座位挤在一起；不要用高柜堵住通风或逃生通道。",
            "xk_avoid_activity": "不要为了摆件堵住门窗或通道；不必只凭此盘改大门、购置鱼缸或增加照明到刺眼。",
            "xk_avoid_rest": "避免把床头或座位紧靠音箱、电视和频繁走动处；无需只凭星数搬床，也别用重物压床。",
            "xk_avoid_everyday": "不必为了星数添购摆件或搬动大件家具；先解决漏水、昏暗、拥堵等实际问题。",

