            "xkd_action_noise": "先處理持續噪音、振動；不額外增加水泵或音箱。",
            "xkd_action_glare": "用遮陽或柔光燈減眩光，保留正常採光與通風。",
            "xkd_action_sleep": "床邊先降噪、遮眩光、穩床頭；床位按實測標記複核。",
            "xkd_action_kitchen": "先查灶邊排煙、隔熱與通道；不憑星數停用或搬灶。",
            "xkd_action_window": "清理窗前遮擋，檢查漏風與遮陽；保留必要換氣。",
            "xkd_action_study": "書桌避開通行動線，補足照明，減少工作時的打擾。",
            "xkd_action_edges": "檢查狹窄交匯處、門扇碰撞與家具尖角，先整理動線。",
            "xkd_action_heat": "檢查電器散熱、插座負荷和熱源間距，清走易燃雜物。",
            "xkd_action_wet": "濕區先修漏水、補排風、做乾濕分離；保留原有必要功能。",
            "xkd_action_corner": "先核對真實外牆輪廓和立極點，確認是否確有缺角。",
            "xkd_action_traffic": "外部道路影響先核對距離、車流與噪音，再考慮隔音遮擋。",
            "xkd_action_wind": "現場核對夾縫來風，先調窗縫密封和可調擋風。",
            "xkd_action_privacy": "複核窗外視線，用可調遮簾改善隱私，保留採光。",
            "xkd_action_structure": "複核外部記錄的實際形態和距離；建築問題交專業人員檢查。",
            "xkd_action_water": "複核現有流水設備的噪音與漏水；先減擾，不新增設備。",
            "xkd_action_work": "此方位列入施工複核；必要維修照常，先控噪、防塵。",
            "xkd_action_separate": "通行活動與安靜座位分開；輕分區，別堵通風和出口。",
            "xkd_action_rest": "穩定座椅靠背，避開頻繁走動處，保留柔和照明與通風。",
            "xkd_action_everyday": "按房間用途處理漏水、昏暗與擁堵，保持整潔。",
            "xkd_action_sanban": "逐宮核對用途與通行；先解決已記錄的干擾，再安排動靜分區。",
            "xkd_action_qixing": "聯看標出的三方門窗與通行，逐方核對開闊、靠實及干擾；不據此增加流水。",
            "xkd_reason_blocked": "現場已記錄通道或門窗受阻。",
            "xkd_reason_noise": "現場已記錄持續噪音或振動。",
            "xkd_reason_glare": "現場已記錄眩光或強烈日曬。",
            "xkd_reason_exterior": "此方位有外部標註，按記錄的距離與現場影響優先複核。",
