            "xkd_reason_water": "靜用方位同時記錄了流水設備，先複核噪音與漏水。",
            "xkd_reason_bed": "此方位覆蓋臥室或有獨立床位標記，優先滿足睡眠需求。",
            "xkd_reason_bed_active": "活動重點與臥室或床位重合，先保安靜，不直接催動。",
            "xkd_reason_kitchen": "此方位覆蓋廚房或灶位，排煙、隔熱與使用便利優先。",
            "xkd_reason_entrance": "此處有大門標記，維持正常出入與通暢。",
            "xkd_reason_heat": "山向或客星組合出現7/9、雙9，加入熱源與電器複核。",
