            "bz_tool_owner": "宅主本命卦",
            "bz_tool_dates": "天星擇日",
            "bz_tool_owner_hint": "個人吉方 · 家屬 · 人宅配對",
            "bz_tool_dates_hint": "查日期 · 選時辰 · 吉日提醒",
            "bz_use_activity": "活動與工作參考位",
            "bz_use_rest": "休息與交流參考位",
            "bz_use_study": "閱讀與專注參考位",
            "bz_use_review": "優先複核使用環境",
            "bz_action_activity": "先疏通走道與門窗，改善照明和通風。如果這裡實際適合辦公或日常活動，再安排桌椅與使用動線。",
            "bz_action_rest": "優先檢查休息座位、床頭支撐、噪音和夜間眩光。若是客廳，安排舒適座位與不互相打擾的交流區。",
            "bz_action_study": "讓桌面整潔、座椅穩定、光線不刺眼，把書桌避開持續噪音源；再按實際讀書或工作習慣微調。",
            "bz_action_review": "先檢查這個方位是否長期睡臥或久坐，以及通風、採光、噪音和雜物。先解決實際不舒適的問題，再考慮小範圍調整。",
            "bz_avoid_activity": "不必只憑吉位改大門、買魚缸或搬動大件；不要為擺件堵住通道。",
            "bz_avoid_rest": "不要用星名代替睡眠或健康判斷，也不必只憑方位搬床；先按真實舒適度處理。",
            "bz_avoid_study": "避免背光、螢幕反光和通道穿過座位；不需要額外購買所謂文昌擺件。",
            "bz_avoid_review": "傳統凶星名稱不是現實事故結論。無需停用房間、改建衛生間或封堵出入口，必要維修仍應照常進行。",

            "xk_guide_center": "住宅中心",
            "xk_pattern_balanced_title": "前方活動，後方休息",
            "xk_pattern_balanced_body": "這張盤的活動重點在朝向一側，休息重點在坐後一側。先看下圖的具體方位；標為「保持安靜」的區域優先按安靜原則處理。",
            "xk_pattern_front_title": "前方做好動靜分區",
            "xk_pattern_front_body": "活動與休息的重點都落在朝向一側。同一方位有兩種需求，要把通行、活動和安靜休息的位置分開，不能整片一概催旺。",
            "xk_pattern_back_title": "後方做好動靜分區",
            "xk_pattern_back_body": "活動與休息的重點都落在坐後一側。先檢查這裡實際是什麼房間，再把動線與安靜區域分開；不是後方所有位置都要擺放重物。",
            "xk_pattern_reversed_title": "前方休息，後方活動",
            "xk_pattern_reversed_body": "這張盤的活動重點在坐後，休息重點在朝向一側。先核對現有用途、採光和噪音，再考慮小範圍調整，不用只憑格局名稱大改房屋。",
            "xk_pattern_distributed_title": "按方位分別安排",
            "xk_pattern_distributed_body": "這張盤不屬於前後集中的四類格局。先查看需要保持安靜的區域，再按下圖分別安排活動和休息用途。",
            "xk_use_quiet": "保持安靜",
            "xk_use_separate": "動靜分區",
            "xk_use_activity": "通暢明亮",
            "xk_use_rest": "安靜穩靠",
            "xk_use_everyday": "日常維護",
            "xk_reason_quiet": "山向組合含2或5，傳統規則以靜為先；即使同時有當運星，本頁也優先提示安靜處理。",
            "xk_reason_separate": "當運山星與向星同在這裡，因此同時有活動和安靜休息兩種需求。",
            "xk_reason_activity": "當運向星落在這裡，傳統上把它作為活動、出入和納氣的重點。",
            "xk_reason_rest": "當運山星落在這裡，傳統上把它作為安靜休息與穩定支撐的重點。",
            "xk_reason_everyday": "這裡沒有觸發本頁的當運山向星或2/5優先規則，按實際房間用途維護即可。",
            "xk_action_quiet": "先移走持續發聲或震動的設備，整理雜物。若這裡是門口，保持通行正常，把門扇異響和碰撞聲處理好。",
            "xk_action_separate": "靠門窗一側留出通道和光線；較內側安排安靜座位或休息區，用家具做輕分區，先避免活動互相干擾。",
            "xk_action_activity": "先疏通門窗與走道，修好照明、保持通風；若實際條件適合，可優先安排日常活動或工作位置。",
            "xk_action_rest": "先減少噪音與夜間眩光，讓床頭、椅背有穩固支撐；保留正常通風，再按實際房間功能調整位置。",
            "xk_action_everyday": "清理雜物，保證照明、通風和通行；按廚房、臥室或工作區的實際需要使用，不必額外改造。",
            "xk_avoid_quiet": "不為「催旺」額外放置水泵、音箱等持續擾動設備，也不用封門或停用房間。必要維修照常安排。",
            "xk_avoid_separate": "別把電視、音箱、水泵與床頭或安靜座位擠在一起；不要用高櫃堵住通風或逃生通道。",
            "xk_avoid_activity": "不要為了擺件堵住門窗或通道；不必只憑此盤改大門、購置魚缸或增加照明到刺眼。",
            "xk_avoid_rest": "避免把床頭或座位緊靠音箱、電視和頻繁走動處；無需只憑星數搬床，也別用重物壓床。",
            "xk_avoid_everyday": "不必為了星數添購擺件或搬動大件家具；先解決漏水、昏暗、擁堵等實際問題。",

