            "xk_reason_rest": "The current-period mountain star is here, traditionally a focus for quiet rest and stable support.",
            "xk_reason_everyday": "No current-period mountain/facing or 2/5 priority rule applies here. Maintain it according to the actual room use.",
            "xk_action_quiet": "Move persistent noise or vibration sources and clear clutter. If this is an entrance, keep it usable and fix squeaking or banging doors.",
            "xk_action_separate": "Keep access and light near doors or windows. Place quiet seating or rest farther inside, using furniture to separate uses without blocking movement.",
            "xk_action_activity": "Clear doors, windows and walkways; restore lighting and airflow. If the room suits it, consider using this area for everyday activity or work.",
            "xk_action_rest": "Reduce noise and nighttime glare, and give beds or chairs stable support. Keep ventilation working and adjust placement to the room’s actual function.",
            "xk_action_everyday": "Clear clutter and maintain light, ventilation and access. Use the space for its real purpose—kitchen, bedroom or workspace—without extra alterations.",
            "xk_avoid_quiet": "Do not add pumps or speakers for “activation.” There is no need to seal an entrance or stop using a room; carry out necessary repairs normally.",
            "xk_avoid_separate": "Keep televisions, speakers and pumps away from beds and quiet seats. Do not block ventilation or escape routes with tall furniture.",
            "xk_avoid_activity": "Do not block doors, windows or walkways with ornaments. The chart alone does not call for a new entrance, an aquarium or glaring lights.",
            "xk_avoid_rest": "Avoid placing beds or seats beside speakers, televisions or busy passageways. Do not move a bed solely for a star number or load it with heavy objects.",
            "xk_avoid_everyday": "No need to buy ornaments or move large furniture for star numbers. Address real issues such as leaks, poor light or blocked access first.",

