            "bz_use_activity": "Aktivitas dan kerja",
            "bz_use_rest": "Istirahat dan kebersamaan",
            "bz_use_study": "Membaca dan fokus",
            "bz_use_review": "Periksa kondisi ruang dahulu",
            "bz_action_activity": "Lapangkan pintu, jendela dan akses; perbaiki cahaya dan udara. Jika cocok untuk kerja atau kegiatan harian, atur meja, kursi dan jalur lewat.",
            "bz_action_rest": "Periksa tempat duduk, penopang tempat tidur, suara dan silau malam. Di ruang keluarga, sediakan kursi nyaman dan area bercakap yang minim gangguan.",
            "bz_action_study": "Jaga meja rapi, kursi stabil dan lampu nyaman. Jauhkan meja dari suara terus-menerus, lalu sesuaikan dengan kebiasaan belajar atau kerja.",
            "bz_action_review": "Periksa penggunaan lama untuk tidur atau duduk, berikut cahaya, udara, suara dan barang berantakan. Atasi ketidaknyamanan nyata dahulu, lalu lakukan perubahan kecil.",
            "bz_avoid_activity": "Tidak perlu mengubah pintu, membeli akuarium atau memindahkan barang besar karena label baik. Jangan menghalangi jalur dengan hiasan.",
            "bz_avoid_rest": "Nama bintang bukan penilaian tidur atau kesehatan. Jangan memindahkan ranjang hanya karena arah; utamakan kenyamanan nyata.",
            "bz_avoid_study": "Hindari cahaya dari belakang, silau layar dan lalu-lalang melewati kursi. Tidak perlu membeli hiasan khusus belajar.",
            "bz_avoid_review": "Nama bintang kurang baik bukan kesimpulan akan terjadi bahaya nyata. Jangan menutup ruangan, mengubahnya jadi kamar mandi atau memblokir akses; perbaikan yang perlu tetap dilakukan.",

            "xk_guide_center": "Pusat rumah",
            "xk_pattern_balanced_title": "Aktivitas depan, istirahat belakang",
            "xk_pattern_balanced_body": "Bagan ini menempatkan fokus aktivitas di sisi hadap dan istirahat di sisi duduk. Lihat sektor di bawah; label “Jaga tenang” selalu didahulukan.",
            "xk_pattern_front_title": "Pisahkan fungsi di depan",
            "xk_pattern_front_body": "Fokus aktivitas dan istirahat berkumpul di sisi hadap. Pisahkan jalur lewat dan aktivitas dari tempat duduk atau istirahat yang tenang; jangan mengaktifkan seluruh sektor sekaligus.",
            "xk_pattern_back_title": "Pisahkan fungsi di belakang",
            "xk_pattern_back_body": "Fokus aktivitas dan istirahat berada di sisi duduk. Kenali ruangannya dahulu, lalu pisahkan sirkulasi dan area tenang; tidak perlu menaruh benda berat di seluruh sisi belakang.",
            "xk_pattern_reversed_title": "Istirahat depan, aktivitas belakang",
            "xk_pattern_reversed_body": "Bagan menempatkan aktivitas di sisi duduk dan istirahat di sisi hadap. Periksa fungsi ruang, cahaya dan kebisingan sebelum perubahan kecil; nama pola saja bukan alasan merenovasi besar.",
            "xk_pattern_distributed_title": "Atur tiap sektor",
            "xk_pattern_distributed_body": "Bagan ini tidak termasuk empat pola depan–belakang. Periksa sektor yang perlu tenang dahulu, lalu gunakan peta untuk menata aktivitas dan istirahat.",
            "xk_use_quiet": "Jaga tenang",
            "xk_use_separate": "Pisahkan fungsi",
            "xk_use_activity": "Terang dan lapang",
            "xk_use_rest": "Tenang dan stabil",
            "xk_use_everyday": "Perawatan biasa",
            "xk_reason_quiet": "Pasangan bintang gunung/hadap memuat 2 atau 5. Aturan tradisional mengutamakan ketenangan, termasuk saat bintang periode berjalan juga hadir.",
            "xk_reason_separate": "Kedua bintang gunung dan hadap periode berjalan ada di sini, sehingga area aktif dan tenang perlu dipisahkan.",
            "xk_reason_activity": "Bintang hadap periode berjalan ada di sini, secara tradisional terkait aktivitas, akses dan penerimaan qi.",
            "xk_reason_rest": "Bintang gunung periode berjalan ada di sini, secara tradisional terkait istirahat yang tenang dan penopang yang stabil.",
            "xk_reason_everyday": "Tidak ada aturan prioritas bintang periode berjalan atau 2/5 di sini. Rawat sesuai fungsi ruangan sebenarnya.",
            "xk_action_quiet": "Pindahkan sumber suara atau getaran terus-menerus dan rapikan barang. Jika ini pintu masuk, jaga tetap berfungsi dan perbaiki bunyi derit atau benturan pintu.",
            "xk_action_separate": "Sisakan akses dan cahaya dekat pintu atau jendela. Tempatkan kursi tenang atau area istirahat lebih ke dalam; gunakan furnitur sebagai pembatas ringan.",
            "xk_action_activity": "Lapangkan pintu, jendela dan jalur lewat; perbaiki pencahayaan dan ventilasi. Jika kondisi cocok, pertimbangkan untuk aktivitas sehari-hari atau bekerja.",
            "xk_action_rest": "Kurangi kebisingan dan silau malam, serta pastikan tempat tidur atau kursi memiliki penopang stabil. Pertahankan ventilasi dan sesuaikan posisi dengan fungsi ruang.",
            "xk_action_everyday": "Rapikan barang serta jaga cahaya, ventilasi dan akses. Gunakan sesuai kebutuhan dapur, kamar tidur atau ruang kerja tanpa perubahan tambahan.",
            "xk_avoid_quiet": "Jangan menambah pompa atau pengeras suara demi “aktivasi.” Tidak perlu menutup akses atau berhenti memakai ruangan; lakukan perbaikan yang diperlukan seperti biasa.",
            "xk_avoid_separate": "Jauhkan TV, pengeras suara dan pompa dari tempat tidur atau kursi tenang. Jangan menghalangi ventilasi atau jalur keluar dengan furnitur tinggi.",
            "xk_avoid_activity": "Jangan menghalangi pintu, jendela atau jalan dengan hiasan. Bagan ini saja bukan alasan mengubah pintu utama, membeli akuarium atau membuat lampu menyilaukan.",
            "xk_avoid_rest": "Hindari tempat tidur atau kursi di dekat pengeras suara, TV atau jalur ramai. Jangan memindahkan ranjang hanya karena angka bintang atau menaruh benda berat di atasnya.",
            "xk_avoid_everyday": "Tidak perlu membeli hiasan atau memindahkan furnitur besar demi angka bintang. Dahulukan masalah nyata seperti kebocoran, kurang cahaya atau akses terhalang.",

