            "bz_use_review": "使用環境を先に確認",
            "bz_action_activity": "通路・扉・窓を空け、採光と通風を整えます。仕事や日常活動に合う部屋なら、机や椅子と動線を配置しましょう。",
            "bz_action_rest": "休息する席やベッドの安定、騒音、夜間のまぶしさを確認します。リビングなら快適な座席と落ち着いて話せる場所を整えましょう。",
            "bz_action_study": "机を整理し、椅子を安定させ、まぶしくない照明を。継続的な騒音源から離し、実際の読書や作業習慣に合わせて調整します。",
            "bz_action_review": "長時間の睡眠や座り作業、通風・採光・騒音・物の多さを確認します。実際の不快さを解消してから、小さな調整を検討しましょう。",
            "bz_avoid_activity": "吉方位という理由だけで玄関の変更や水槽購入、大型家具の移動は不要です。置物で通路を塞がないようにしましょう。",
            "bz_avoid_rest": "星名で睡眠や健康を判断せず、方位だけでベッドを移す必要はありません。実際の快適さを優先しましょう。",
            "bz_avoid_study": "逆光・画面の反射・座席を横切る動線を避け、学業用とされる置物を買い足す必要はありません。",
            "bz_avoid_review": "伝統的な凶星名は現実の事故を示す結論ではありません。部屋の使用停止、浴室への改造、出入口の閉鎖は不要で、必要な修理は行ってください。",

            "xk_guide_center": "住まいの中心",
            "xk_pattern_balanced_title": "前方で活動、後方で休息",
            "xk_pattern_balanced_body": "この盤では向き側が活動、背面側が休息の重点です。下図の方位を確認し、「静かに使う」の表示がある場所はそちらを優先してください。",
            "xk_pattern_front_title": "前方の動静を分ける",
            "xk_pattern_front_body": "活動と休息の重点が向き側に集まります。通路・活動場所と静かな居場所を分け、方位全体を一律に活性化しない配置が基本です。",
            "xk_pattern_back_title": "後方の動静を分ける",
            "xk_pattern_back_body": "活動と休息の重点が背面側に集まります。実際の部屋を確認して動線と静かな場所を分けましょう。後方すべてに重い物を置く必要はありません。",
            "xk_pattern_reversed_title": "前方で休息、後方で活動",
            "xk_pattern_reversed_body": "活動の重点が背面側、休息の重点が向き側です。用途・採光・騒音を確認してから小さな調整を考え、格局名だけで大改装をしないようにしましょう。",
            "xk_pattern_distributed_title": "方位ごとに配置",
            "xk_pattern_distributed_body": "前後に集中する四つの格局には当てはまりません。まず静けさを優先する方位を確認し、下図に沿って活動と休息を配置します。",
            "xk_use_quiet": "静かに使う",
            "xk_use_separate": "用途を分ける",
            "xk_use_activity": "明るく開放",
            "xk_use_rest": "静かで安定",
            "xk_use_everyday": "日常の手入れ",
            "xk_reason_quiet": "山星・向星に2または5が含まれ、伝統上は静けさを優先します。当運星が重なっていても、このページでは静かな使い方を先に示します。",
            "xk_reason_separate": "当運の山星と向星が同じ方位にあり、活動と静かな休息の両方を考える配置です。",
            "xk_reason_activity": "当運の向星があり、伝統上は活動・出入り・気の取り込みの重点とされます。",
            "xk_reason_rest": "当運の山星があり、伝統上は静かな休息と安定した支えの重点とされます。",
            "xk_reason_everyday": "当運の山星・向星や2・5の優先ルールには該当しません。実際の部屋の用途に合わせて整えましょう。",
            "xk_action_quiet": "音や振動が続く機器を移し、物を整理しましょう。玄関なら通常の通行を保ち、扉のきしみや衝突音を直します。",
            "xk_action_separate": "扉や窓側は通路と採光を確保し、内側に静かな座席や休息場所を。家具で軽く区切り、互いの活動が干渉しないようにします。",
            "xk_action_activity": "扉・窓・通路を空け、照明と通風を整えましょう。実際の条件に合うなら、日常の活動や作業の場所として検討できます。",
            "xk_action_rest": "騒音と夜間のまぶしさを減らし、ベッドや椅子を安定させましょう。通風を確保し、実際の用途に合わせて位置を調整します。",
            "xk_action_everyday": "物を整理し、照明・通風・通路を確保しましょう。キッチン・寝室・作業場など本来の用途で使い、特別な改造は不要です。",
            "xk_avoid_quiet": "「活性化」のためにポンプやスピーカーを追加しないこと。入口を塞いだり部屋を使わなくする必要はなく、必要な修理は行ってください。",
            "xk_avoid_separate": "テレビ・スピーカー・ポンプはベッドや静かな席から離し、背の高い家具で通風や避難路を塞がないようにしましょう。",
            "xk_avoid_activity": "置物で扉・窓・通路を塞がず、この盤だけを理由に玄関の変更や水槽の購入、過剰な照明を行う必要はありません。",
            "xk_avoid_rest": "ベッドや座席をスピーカー・テレビ・頻繁な通路に密接させないこと。星の番号だけでベッドを移したり、重い物を載せる必要はありません。",
            "xk_avoid_everyday": "星の番号のために置物を買ったり大型家具を動かす必要はありません。水漏れ・暗さ・通路の詰まりなど実際の問題を先に直しましょう。",

