            "xk_reason_quiet": "산성·향성에 2 또는 5가 있어 전통상 조용한 사용을 우선합니다. 당운성이 함께 있어도 이 안내를 먼저 적용합니다.",
            "xk_reason_separate": "당운 산성과 향성이 함께 있어 활동과 조용한 휴식이라는 두 용도를 나눠야 합니다.",
            "xk_reason_activity": "당운 향성이 있어 전통상 활동·출입·기운 유입의 중심으로 봅니다.",
            "xk_reason_rest": "당운 산성이 있어 전통상 고요한 휴식과 안정된 지지를 중심으로 봅니다.",
            "xk_reason_everyday": "당운 산성·향성 또는 2·5 우선 규칙에 해당하지 않습니다. 실제 방의 용도에 맞게 관리하면 됩니다.",
            "xk_action_quiet": "지속적으로 소리나 진동을 내는 기기를 옮기고 물건을 정리하세요. 출입구라면 통행을 유지하고 문 삐걱임과 충돌음을 줄이세요.",
            "xk_action_separate": "문·창가에는 통로와 빛을 확보하고 안쪽에 조용한 좌석이나 휴식 구역을 두세요. 가구로 가볍게 나눠 서로 방해하지 않게 하세요.",
            "xk_action_activity": "문·창문·통로를 정리하고 조명과 환기를 개선하세요. 실제 환경이 맞는다면 일상 활동이나 작업 공간으로 고려하세요.",
            "xk_action_rest": "소음과 야간 눈부심을 줄이고 침대 머리맡과 의자 등받이를 안정되게 하세요. 정상 환기를 유지하며 실제 방의 기능에 맞춰 위치를 조정하세요.",
            "xk_action_everyday": "물건을 정리하고 조명·환기·통행을 확보하세요. 주방·침실·작업실 등 실제 필요에 맞게 쓰면 되며 별도 개조는 필요하지 않습니다.",
            "xk_avoid_quiet": "활성화를 위해 펌프나 스피커를 추가하지 마세요. 문을 막거나 방 사용을 중단할 필요는 없으며 필요한 수리는 평소대로 진행하세요.",
            "xk_avoid_separate": "TV·스피커·펌프를 침대나 조용한 좌석에 붙이지 말고 높은 가구로 환기나 대피 동선을 막지 마세요.",
            "xk_avoid_activity": "장식품으로 문·창문·통로를 막지 마세요. 이 명반만을 근거로 현관을 바꾸거나 어항을 사거나 눈부시게 조명을 늘릴 필요는 없습니다.",
            "xk_avoid_rest": "침대 머리맡이나 좌석을 스피커·TV·잦은 통행 구역에 붙이지 마세요. 별 번호만으로 침대를 옮기거나 무거운 물건을 올리지 마세요.",
